#!/usr/bin/env python3
"""
Minimal UDP DNS server.

Steps:
1. Create a UDP socket and bind it to the requested IP address and port.
2. Receive a datagram and record the sender address.
3. Parse the DNS header and the first question (QNAME, QTYPE, QCLASS),
   handling label compression pointers.
4. Resolve the question:
   a. Answer from the local authoritative zone if the name is known.
   b. Otherwise forward the original query to an upstream resolver over UDP.
   c. If neither works, answer with NXDOMAIN or SERVFAIL.
5. Build a DNS response that reuses the query ID and question section.
6. Send the response back to the requesting address over UDP.
"""

import argparse
import socket
import struct
import sys

TYPE_A = 1
TYPE_NS = 2
TYPE_CNAME = 5
TYPE_PTR = 12
TYPE_TXT = 16
TYPE_AAAA = 28

TYPE_NAMES = {
    "A": TYPE_A,
    "NS": TYPE_NS,
    "CNAME": TYPE_CNAME,
    "PTR": TYPE_PTR,
    "TXT": TYPE_TXT,
    "AAAA": TYPE_AAAA,
}

RCODE_NOERROR = 0
RCODE_FORMERR = 1
RCODE_SERVFAIL = 2
RCODE_NXDOMAIN = 3

DEFAULT_TTL = 300


def encode_name(name):
    name = name.strip(".")
    if not name:
        return b"\x00"
    out = bytearray()
    for label in name.split("."):
        raw = label.encode("ascii")
        if len(raw) == 0 or len(raw) > 63:
            raise ValueError("invalid DNS label: %r" % label)
        out.append(len(raw))
        out.extend(raw)
    out.append(0)
    return bytes(out)


def parse_name(data, offset):
    """Parse a possibly compressed domain name. Returns (name, offset_after_name)."""
    labels = []
    end = None
    jumps = 0
    while True:
        if offset >= len(data):
            raise ValueError("name runs past end of packet")
        length = data[offset]
        if length & 0xC0 == 0xC0:
            if offset + 1 >= len(data):
                raise ValueError("truncated compression pointer")
            pointer = ((length & 0x3F) << 8) | data[offset + 1]
            if end is None:
                end = offset + 2
            jumps += 1
            if jumps > 50:
                raise ValueError("compression pointer loop")
            offset = pointer
            continue
        if length & 0xC0:
            raise ValueError("unsupported label type")
        if length == 0:
            if end is None:
                end = offset + 1
            break
        offset += 1
        if offset + length > len(data):
            raise ValueError("label runs past end of packet")
        labels.append(data[offset:offset + length].decode("ascii", "replace"))
        offset += length
    return ".".join(labels).lower(), end


def parse_query(data):
    """Parse the DNS header and first question of a query packet."""
    if len(data) < 12:
        raise ValueError("packet too short for DNS header")
    qid, flags, qdcount, ancount, nscount, arcount = struct.unpack("!HHHHHH", data[:12])
    if qdcount < 1:
        raise ValueError("no question present")
    qname, off = parse_name(data, 12)
    if off + 4 > len(data):
        raise ValueError("truncated question section")
    qtype, qclass = struct.unpack("!HH", data[off:off + 4])
    return {
        "id": qid,
        "flags": flags,
        "opcode": (flags >> 11) & 0xF,
        "rd": bool(flags & 0x0100),
        "qname": qname,
        "qtype": qtype,
        "qclass": qclass,
        "question_end": off + 4,
    }


def make_rdata(rtype, value):
    """Convert a human-readable record value into wire-format RDATA."""
    if rtype == TYPE_A:
        return socket.inet_pton(socket.AF_INET, value)
    if rtype == TYPE_AAAA:
        return socket.inet_pton(socket.AF_INET6, value)
    if rtype in (TYPE_NS, TYPE_CNAME, TYPE_PTR):
        return encode_name(value)
    if rtype == TYPE_TXT:
        raw = value.encode("utf-8")[:255]
        return bytes([len(raw)]) + raw
    raise ValueError("unsupported record type %d" % rtype)


def lookup_local(zone, qname, qtype):
    """
    zone: dict mapping lowercase names to {type_int: [(ttl, value_str), ...]}
    Returns (name_known, list_of_(rtype, ttl, rdata)).
    """
    entry = zone.get(qname.lower().strip("."))
    if entry is None:
        return False, []
    answers = []
    if qtype in entry:
        for ttl, value in entry[qtype]:
            answers.append((qtype, ttl, make_rdata(qtype, value)))
    return True, answers


def forward_query(data, upstream, timeout=2.0):
    """Relay the raw query to an upstream resolver and return its raw response."""
    family = socket.AF_INET6 if ":" in upstream[0] else socket.AF_INET
    with socket.socket(family, socket.SOCK_DGRAM) as s:
        s.settimeout(timeout)
        try:
            s.sendto(data, upstream)
            while True:
                resp, _ = s.recvfrom(4096)
                if len(resp) >= 2 and resp[:2] == data[:2]:
                    return resp
        except (socket.timeout, OSError):
            return None


